"""Lazy Native actor setup from a validated original map packet.

Callers supply CARLA transforms and blueprint library; no CARLA import occurs on
CPU. Spawn failures clean up actors owned by this construction.
"""
from backing_geometry import validate


def construct(world, packet, transforms):
    reviewed = validate(packet)
    if set(transforms) != {"vehicle", "pedestrian"} or any(transforms[k] is None for k in transforms):
        raise ValueError("source-bound Native vehicle and pedestrian transforms required")
    native_map = world.get_map()
    if native_map.name != packet["map_name"]:
        raise ValueError("Native map identity differs from original packet")
    library = world.get_blueprint_library()
    vehicle_bp = library.find(reviewed["vehicle_blueprint_id"])
    pedestrian_bp = library.find(reviewed["pedestrian_blueprint_id"])
    owned = []
    try:
        for blueprint, key in ((vehicle_bp,"vehicle"),(pedestrian_bp,"pedestrian")):
            actor = world.try_spawn_actor(blueprint, transforms[key])
            if actor is None:
                raise ValueError("Native actor spawn failed: " + key)
            owned.append(actor)
            if actor.type_id != blueprint.id:
                raise ValueError("Native actor blueprint readback differs: " + key)
        return {"vehicle": owned[0], "pedestrian": owned[1],
                "map_sha256": reviewed["map_sha256"], "junction_id": reviewed["junction_id"],
                "cleanup": lambda: [actor.destroy() for actor in reversed(owned)]}
    except Exception:
        for actor in reversed(owned):
            actor.destroy()
        raise

"""Finite reverse/yield controller with explicit CARLA control injection."""


class BackingController:
    def __init__(self, *, yield_for_pedestrian, control_factory=None):
        if not isinstance(yield_for_pedestrian, bool):
            raise ValueError("yield policy must be explicit")
        self.yield_for_pedestrian = yield_for_pedestrian
        self.control_factory = control_factory or (lambda **values: values)

    def step(self, vehicle, *, pedestrian_in_corridor, phase):
        if phase not in ("hold", "backing", "complete"):
            raise ValueError("unknown controller phase")
        if not isinstance(pedestrian_in_corridor, bool):
            raise ValueError("pedestrian corridor state missing")
        hold = phase in ("hold", "complete") or (self.yield_for_pedestrian and pedestrian_in_corridor)
        command = {"reverse": True, "throttle": 0.0 if hold else 0.18,
                   "brake": 1.0 if hold else 0.0, "hand_brake": False}
        vehicle.apply_control(self.control_factory(**command))
        return command

"""Source-gated Native geometry for an intersection backing interaction.

This module never asserts that a named cell has a usable reverse path. The
operator must export an original CARLA/OpenDRIVE packet and validate it first.
"""
from math import hypot, isfinite


def _point(value):
    if not isinstance(value, dict) or not all(k in value for k in ("x_m", "y_m", "source_ref")):
        raise ValueError("original coordinate and source reference required")
    if not value["source_ref"]:
        raise ValueError("empty coordinate source")
    point = float(value["x_m"]), float(value["y_m"])
    if not all(isfinite(coordinate) for coordinate in point):
        raise ValueError("finite original coordinate required")
    return point


def _distance_to_segment(point, start, end):
    dx, dy = end[0] - start[0], end[1] - start[1]
    length2 = dx * dx + dy * dy
    if length2 <= 0:
        raise ValueError("degenerate route segment")
    fraction = max(0.0, min(1.0, ((point[0]-start[0])*dx+(point[1]-start[1])*dy)/length2))
    return hypot(point[0]-start[0]-fraction*dx, point[1]-start[1]-fraction*dy)


def _segment_gap(a, b, c, d):
    def cross(u, v, p):
        return (v[0]-u[0])*(p[1]-u[1])-(v[1]-u[1])*(p[0]-u[0])
    if cross(a,b,c)*cross(a,b,d) <= 0 and cross(c,d,a)*cross(c,d,b) <= 0:
        return 0.0
    return min(_distance_to_segment(p, u, v) for p,u,v in
               ((a,c,d),(b,c,d),(c,a,b),(d,a,b)))


def validate(packet):
    """Return source identities and conflict geometry, not physical acceptance."""
    required = ("map_sha256", "map_name", "junction_id", "vehicle_blueprint_id",
                "pedestrian_blueprint_id", "vehicle_reverse_route", "pedestrian_route",
                "vehicle_half_width_m", "pedestrian_radius_m", "control_source")
    if any(k not in packet for k in required):
        raise ValueError("incomplete original Native map and actor packet")
    if len(packet["map_sha256"]) != 64 or not packet["map_name"] or packet["junction_id"] is None:
        raise ValueError("original source-hashed map junction required")
    if not packet["control_source"] or not packet["vehicle_blueprint_id"].startswith("vehicle."):
        raise ValueError("original vehicle and control source required")
    if not packet["pedestrian_blueprint_id"].startswith("walker.pedestrian."):
        raise ValueError("original pedestrian blueprint required")
    vehicle = packet["vehicle_reverse_route"]
    pedestrian = packet["pedestrian_route"]
    if len(vehicle) < 2 or len(pedestrian) < 2:
        raise ValueError("connected reverse and pedestrian routes required")
    if any(p.get("junction_id") != packet["junction_id"] for p in vehicle):
        raise ValueError("vehicle reverse route not bound to original junction")
    v = [_point(p) for p in vehicle]
    w = [_point(p) for p in pedestrian]
    if any(hypot(v[i+1][0]-v[i][0], v[i+1][1]-v[i][1]) < .1 for i in range(len(v)-1)):
        raise ValueError("vehicle reverse route contains degenerate segment")
    if any(hypot(w[i+1][0]-w[i][0], w[i+1][1]-w[i][1]) < .1 for i in range(len(w)-1)):
        raise ValueError("pedestrian route contains degenerate segment")
    width = float(packet["vehicle_half_width_m"])
    radius = float(packet["pedestrian_radius_m"])
    if not isfinite(width) or not isfinite(radius) or width <= 0 or radius <= 0:
        raise ValueError("actor extents must be positive")
    closest = min(_segment_gap(v[i],v[i+1],w[j],w[j+1])
                  for i in range(len(v)-1) for j in range(len(w)-1))
    if closest > width + radius:
        raise ValueError("pedestrian route misses reverse body corridor")
    return {"map_sha256": packet["map_sha256"], "junction_id": packet["junction_id"],
            "vehicle_blueprint_id": packet["vehicle_blueprint_id"],
            "pedestrian_blueprint_id": packet["pedestrian_blueprint_id"],
            "route_gap_m": closest, "route_conflict": True,
            "physical_realization": "pending original Native execution"}


def pedestrian_in_reverse_corridor(packet, pedestrian_xy):
    """Compute route-corridor occupancy from original map and person position."""
    validate(packet)
    if (not isinstance(pedestrian_xy, (list, tuple)) or len(pedestrian_xy) != 2 or
            any(type(value) not in (int, float) or not isfinite(value)
                for value in pedestrian_xy)):
        raise ValueError("finite original pedestrian position required")
    route = [_point(point) for point in packet["vehicle_reverse_route"]]
    person = tuple(float(value) for value in pedestrian_xy)
    gap = min(_distance_to_segment(person, a, b)
              for a, b in zip(route, route[1:]))
    limit = float(packet["vehicle_half_width_m"]) + float(packet["pedestrian_radius_m"])
    return {"in_corridor": gap <= limit, "distance_to_reverse_route_m": gap,
            "corridor_extent_m": limit,
            "basis": "original_map_reverse_route_and_original_pedestrian_position"}

"""Original-frame measurements and source-bound controlled comparison.

The measured timeline preserves uncertainty about statutory right of way.
"""
from math import hypot


def _xy(value):
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError("original XY sample required")
    return float(value[0]), float(value[1])


def measure(frames, *, source_id, map_sha256, vehicle_actor_id, pedestrian_actor_id):
    if not source_id or len(map_sha256) != 64 or not frames:
        raise ValueError("original source and map hash required")
    if vehicle_actor_id == pedestrian_actor_id or vehicle_actor_id is None or pedestrian_actor_id is None:
        raise ValueError("distinct original actors required")
    rows = []
    previous_frame, previous_time = -1, -1.0
    for sample in frames:
        required = ("frame", "time_s", "vehicle_actor_id", "pedestrian_actor_id",
                    "vehicle_xy", "pedestrian_xy", "vehicle_velocity_xy",
                    "vehicle_forward_xy", "pedestrian_velocity_xy", "brake",
                    "reverse_gear", "pedestrian_in_corridor")
        if any(k not in sample for k in required):
            raise ValueError("missing original frame measurement")
        index, now = int(sample["frame"]), float(sample["time_s"])
        if index <= previous_frame or now <= previous_time:
            raise ValueError("original frame and time must increase")
        if sample["vehicle_actor_id"] != vehicle_actor_id or sample["pedestrian_actor_id"] != pedestrian_actor_id:
            raise ValueError("original actor identity changed")
        previous_frame, previous_time = index, now
        car, person = _xy(sample["vehicle_xy"]), _xy(sample["pedestrian_xy"])
        velocity, forward = _xy(sample["vehicle_velocity_xy"]), _xy(sample["vehicle_forward_xy"])
        pedestrian_velocity = _xy(sample["pedestrian_velocity_xy"])
        reverse_speed = -(velocity[0]*forward[0]+velocity[1]*forward[1])
        rows.append({"frame": index, "time_s": now, "pedestrian_gap_m": hypot(car[0]-person[0], car[1]-person[1]),
                     "reverse_speed_mps": reverse_speed, "brake": float(sample["brake"]),
                     "reverse_gear": bool(sample["reverse_gear"]),
                     "pedestrian_speed_mps": hypot(*pedestrian_velocity),
                     "pedestrian_in_corridor": bool(sample["pedestrian_in_corridor"])})
    if not any(r["reverse_gear"] and r["reverse_speed_mps"] > .05 for r in rows):
        raise ValueError("backing not observed in original frames")
    if not any(r["pedestrian_in_corridor"] and r["pedestrian_speed_mps"] > .05 for r in rows):
        raise ValueError("moving pedestrian conflict not observed")
    return {"source_id": source_id, "map_sha256": map_sha256, "frames": rows,
            "vehicle_actor_id": vehicle_actor_id, "pedestrian_actor_id": pedestrian_actor_id,
            "legal_judgment": "unresolved"}


def compare(left, right):
    if left["map_sha256"] != right["map_sha256"] or left["source_id"] == right["source_id"]:
        raise ValueError("comparison needs common map and distinct original sources")
    a, b = left["frames"], right["frames"]
    if len(a) != len(b) or [r["frame"] for r in a] != [r["frame"] for r in b]:
        raise ValueError("comparison frame window differs")
    fixed = ("pedestrian_in_corridor", "pedestrian_speed_mps", "pedestrian_gap_m")
    if any(any(abs(x[key]-y[key]) > .02 if isinstance(x[key], float) else x[key] != y[key]
               for key in fixed) for x,y in zip(a,b)):
        raise ValueError("pedestrian exposure differs across yield comparison")
    if not any(x["reverse_speed_mps"] != y["reverse_speed_mps"] or x["brake"] != y["brake"]
               for x,y in zip(a,b)):
        raise ValueError("no observed driver-response difference")
    return {"sources": [left["source_id"], right["source_id"]],
            "fixed_observables": list(fixed), "changed_observables": ["reverse_speed_mps", "brake"],
            "legal_judgment": "unresolved"}

"""Case-specific, measured backing response witnesses.

Thresholds below distinguish the two engineered controller policies. They do
not define statutory yielding or establish pedestrian right of way.
"""
from __future__ import annotations

from math import isfinite


WINDOW_FRAMES = 20
MIN_FRAME = 20


def response_witness(measurement, *, case_id):
    if case_id.endswith("__pedestrian_yield"):
        policy = "pedestrian_yield"
    elif case_id.endswith("__pedestrian_continue"):
        policy = "pedestrian_continue"
    else:
        raise ValueError("unknown backing response case")
    frames = measurement.get("frames")
    if not isinstance(frames, list) or len(frames) < WINDOW_FRAMES:
        raise ValueError("original measured response frames missing")
    for start in range(len(frames) - WINDOW_FRAMES + 1):
        window = frames[start:start + WINDOW_FRAMES]
        if window[0]["frame"] < MIN_FRAME:
            continue
        if any(row["frame"] != window[0]["frame"] + offset
               for offset, row in enumerate(window)):
            continue
        if not all(row["pedestrian_in_corridor"] and row["pedestrian_speed_mps"] > .05
                   and row["reverse_gear"] for row in window):
            continue
        if not all(isfinite(row["brake"]) and isfinite(row["reverse_speed_mps"])
                   for row in window):
            raise ValueError("nonfinite original driver response")
        if policy == "pedestrian_yield":
            matched = all(row["brake"] >= .5 and row["reverse_speed_mps"] <= .3
                          for row in window)
        else:
            matched = all(row["brake"] <= .1 and row["reverse_speed_mps"] >= .4
                          for row in window)
        if matched:
            return {"policy": policy, "source_id": measurement["source_id"],
                    "first_frame": window[0]["frame"], "last_frame": window[-1]["frame"],
                    "pedestrian_speed_min_mps": min(row["pedestrian_speed_mps"] for row in window),
                    "reverse_speed_min_mps": min(row["reverse_speed_mps"] for row in window),
                    "reverse_speed_max_mps": max(row["reverse_speed_mps"] for row in window),
                    "brake_min": min(row["brake"] for row in window),
                    "brake_max": max(row["brake"] for row in window),
                    "witness_kind": "original_frame_engineering_response",
                    "legal_judgment": "unresolved"}
    raise ValueError("case-specific moving-pedestrian response witness missing")

"""Spawn two source-specified Native vehicles for moving-traffic backing."""
from traffic_geometry import validate


def construct(world, packet, transforms):
    reviewed = validate(packet)
    if set(transforms) != {'vehicle', 'traffic'} or any(transforms[key] is None for key in transforms):
        raise ValueError('two reviewed original vehicle transforms required')
    if world.get_map().name != packet['map_name']:
        raise ValueError('original Native moving-traffic map identity differs')
    library = world.get_blueprint_library()
    blueprints = {key: library.find(packet[name]) for key, name in
                  (('vehicle', 'vehicle_blueprint_id'), ('traffic', 'traffic_blueprint_id'))}
    owned = []
    try:
        for key in ('vehicle', 'traffic'):
            actor = world.try_spawn_actor(blueprints[key], transforms[key])
            if actor is None:
                raise ValueError('Native moving-traffic actor spawn failed: ' + key)
            owned.append(actor)
            if actor.type_id != blueprints[key].id:
                raise ValueError('Native moving-traffic actor blueprint readback differs: ' + key)
        return {'vehicle': owned[0], 'traffic': owned[1],
                'map_sha256': reviewed['map_sha256'], 'junction_id': reviewed['junction_id'],
                'cleanup': lambda: [actor.destroy() for actor in reversed(owned)]}
    except BaseException:
        for actor in reversed(owned):
            actor.destroy()
        raise

